/**
 * @summary Get calendar events (requests + public holidays) for a given month
 */
export const getGetTimeOffCalendarUrl = (params: GetTimeOffCalendarParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/time-off/calendar?${stringifiedParams}` : `/api/time-off/calendar`
}

