/**
 * Returns authorized operational-ledger entries for this base item with a running balance consolidated across the selected permitted locations. Requires base_items.view or base_items.manage page access (or owner); location-restricted members only receive rows from assigned locations.

 * @summary Paginated stock movement ledger for a base item
 */
export const getGetBaseItemStockMovementsUrl = (id: number,
    params?: GetBaseItemStockMovementsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/base-items/${id}/stock-movements?${stringifiedParams}` : `/api/base-items/${id}/stock-movements`
}

