/**
 * @summary List supplier statement collection requests
 */
export const getListSupplierStatementRequestsUrl = (params?: ListSupplierStatementRequestsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/supplier-statement-requests?${stringifiedParams}` : `/api/supplier-statement-requests`
}

