/**
 * Returns all non-deleted drivers in the workspace. Supports filtering by status and free-text search.
 * @summary List drivers
 */
export const getListFleetDriversUrl = (params?: ListFleetDriversParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/fleet/drivers?${stringifiedParams}` : `/api/fleet/drivers`
}

