/**
 * @summary List the authenticated driver's wallet transactions
 */
export const getFleetListMyTransactionsUrl = (params?: FleetListMyTransactionsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/fleet/me/transactions?${stringifiedParams}` : `/api/fleet/me/transactions`
}

