/**
 * Returns a structured delivery catalog for the resolved workspace: all active cities with their active districts/areas, scheduled timeslots, and any active special-day overrides. Intended for external website integration.
The workspace can be identified via an API key (`Authorization: Bearer pk_live_...`) or the `workspace` query parameter (workspace owner ID). If both are supplied the API key takes precedence. At least one must be provided.

 * @summary External API — full delivery catalog (cities, timeslots, special overrides)
 */
export const getGetDeliveryCatalogUrl = (params?: GetDeliveryCatalogParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/delivery-catalog?${stringifiedParams}` : `/api/delivery-catalog`
}

export const getDeliveryCatalog = async (params?: GetDeliveryCatalogParams, options?: RequestInit): Promise<DeliveryCatalogResponse> => {

  return customFetch<DeliveryCatalogResponse>(getGetDeliveryCatalogUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetDeliveryCatalogQueryKey = (params?: GetDeliveryCatalogParams,) => {
    return [
    `/api/delivery-catalog`, ...(params ? [params] : [])
    ] as const;
    }


export const getGetDeliveryCatalogQueryOptions = <TData = Awaited<ReturnType<typeof getDeliveryCatalog>>, TError = ErrorType<void>>(params?: GetDeliveryCatalogParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getDeliveryCatalog>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetDeliveryCatalogQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getDeliveryCatalog>>> = ({ signal }) => getDeliveryCatalog(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getDeliveryCatalog>>, TError, TData> & { queryKey: QueryKey }
}

export type GetDeliveryCatalogQueryResult = NonNullable<Awaited<ReturnType<typeof getDeliveryCatalog>>>
export type GetDeliveryCatalogQueryError = ErrorType<void>


/**
 * @summary External API — full delivery catalog (cities, timeslots, special overrides)
 */

export function useGetDeliveryCatalog<TData = Awaited<ReturnType<typeof getDeliveryCatalog>>, TError = ErrorType<void>>(
 params?: GetDeliveryCatalogParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getDeliveryCatalog>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetDeliveryCatalogQueryOptions(params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return { ...query, queryKey: queryOptions.queryKey };
}







/**
 * Returns the workspace's products in a camelCase shape suitable for an external storefront. Requires a workspace API key (`Authorization: Bearer pk_live_...`); without one the request falls through to the internal Clerk-authenticated products endpoint, which returns a different (snake_case) shape.
Each product carries a stable string `sku` identifier (echo it back as the order line item's `productId`), absolute image URLs, and `deliverableCities` / `deliverableCountries`. When a product has no explicit per-product city-availability rows the deliverable lists fall back to the workspace's configured active delivery cities / countries.
`pageSize` accepts any positive integer and is capped at 100 (default 25).

 * @summary External API — list products for a storefront (API-key authenticated)
 */
