/**
 * Returns the workspace's SEO metric rows, newest period first. Optional `from` and `to` (YYYY-MM-DD) filters. Owner only.

 * @summary List SEO metrics
 */
export const getListSeoMetricsUrl = (params?: ListSeoMetricsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/seo-metrics?${stringifiedParams}` : `/api/seo-metrics`
}

