/**
 * Returns a paginated, searchable picker model scoped to the order's delivery country and city. Prices are resolved server-side in the order's display currency and use the same calculation as the add-line mutation. Products explicitly disabled for the market are excluded; products whose price cannot be resolved remain visible but unavailable. Requires Orders page access.

 * @summary List products eligible to add to an order
 */
export const getListOrderLineItemCatalogUrl = (id: string,
    params?: ListOrderLineItemCatalogParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/orders/${id}/line-items?${stringifiedParams}` : `/api/orders/${id}/line-items`
}

