/**
 * Members with the `florist_orders` page see only assignments for their own florist location (workspace_members.florist_location_id, enforced server-side; 403 when unset). Owners see all locations, optionally filtered by `location_id`. Responses exclude customer PII — order number, line items, and card availability only.

 * @summary List florist order assignments (florist queue)
 */
export const getListFloristOrdersUrl = (params?: ListFloristOrdersParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/florist-orders?${stringifiedParams}` : `/api/florist-orders`
}

