/**
 * Looks up stored exchange rates, applies the workspace markup and rounding rule, and returns a full conversion breakdown.

 * @summary Convert an amount between two currencies using stored rates
 */
export const getConvertExchangeRateUrl = (params: ConvertExchangeRateParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/exchange-rates/convert?${stringifiedParams}` : `/api/exchange-rates/convert`
}

