/**
 * The workspace can be identified via an API key (`Authorization: Bearer pk_live_...`), a `workspace_owner_id` query parameter, or a `city_id`/`city_slug` query parameter.

 * @summary Get active recipients. No authentication required. At least one of city_id, city_slug, workspace_owner_id, or a Bearer API key is required.

 */
export const getGetPublicCatalogAttributeRecipientsUrl = (params?: GetPublicCatalogAttributeRecipientsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/catalog-attributes/recipients?${stringifiedParams}` : `/api/catalog-attributes/recipients`
}

