/**
 * @summary List knowledge base articles for the workspace
 */
export const getListOmniKnowledgeBaseUrl = (params?: ListOmniKnowledgeBaseParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/omnichannel/knowledge-base?${stringifiedParams}` : `/api/omnichannel/knowledge-base`
}

