/**
 * Paginated list of audiences for the workspace with cached evaluation counts. By default archived audiences are hidden; pass `status` to filter explicitly. Requires the `audiences` (or `customers`) page.

 * @summary List audiences
 */
export const getListAudiencesUrl = (params?: ListAudiencesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/audiences?${stringifiedParams}` : `/api/audiences`
}

