/**
 * Returns the audience with cached counts and rule summary.
 * @summary Get one audience
 */
export const getGetAudienceUrl = (id: string,) => {




  return `/api/audiences/${id}`
}

export const getAudience = async (id: string, options?: RequestInit): Promise<AudienceResponse> => {

  return customFetch<AudienceResponse>(getGetAudienceUrl(id),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetAudienceQueryKey = (id: string,) => {
    return [
    `/api/audiences/${id}`
    ] as const;
    }


export const getGetAudienceQueryOptions = <TData = Awaited<ReturnType<typeof getAudience>>, TError = ErrorType<void>>(id: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getAudience>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetAudienceQueryKey(id);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getAudience>>> = ({ signal }) => getAudience(id, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: !!(id), ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getAudience>>, TError, TData> & { queryKey: QueryKey }
}

export type GetAudienceQueryResult = NonNullable<Awaited<ReturnType<typeof getAudience>>>
export type GetAudienceQueryError = ErrorType<void>


/**
 * @summary Get one audience
 */

export function useGetAudience<TData = Awaited<ReturnType<typeof getAudience>>, TError = ErrorType<void>>(
 id: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getAudience>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetAudienceQueryOptions(id,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return { ...query, queryKey: queryOptions.queryKey };
}







