/**
 * Dynamic audiences are evaluated live via the shared evaluator (with evidence); static audiences read their explicit membership records.

 * @summary Paginated audience members
 */
export const getGetAudienceContactsUrl = (id: string,
    params?: GetAudienceContactsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/audiences/${id}/contacts?${stringifiedParams}` : `/api/audiences/${id}/contacts`
}

export const getAudienceContacts = async (id: string,
    params?: GetAudienceContactsParams, options?: RequestInit): Promise<AudienceContactsResponse> => {

  return customFetch<AudienceContactsResponse>(getGetAudienceContactsUrl(id,params),
  {
    ...options,
    method: 'GET'


  }
);}





