/**
 * Paginated, newest-first timeline combining manual notes, system activity entries (edits, merges), the contact-created event, and order events (`order_placed` for customer-role orders, `gift_received` for recipient-role orders).

 * @summary Combined activity timeline for a contact
 */
export const getListContactActivityUrl = (id: string,
    params?: ListContactActivityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/contacts/${id}/activity?${stringifiedParams}` : `/api/contacts/${id}/activity`
}

